CREATE TABLE IF NOT EXISTS product_gallery (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, image VARCHAR(1000) NOT NULL, alt_text VARCHAR(180) NOT NULL DEFAULT '', sort_order INT NOT NULL DEFAULT 0, INDEX(product_id,sort_order,id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS category_channels (category_id INT PRIMARY KEY, in_store TINYINT(1) NOT NULL DEFAULT 0) ENGINE=InnoDB;
